INSERT INTO `douyin_aweme` VALUES (65, '104255897823', 'MS4wLjABAAAA8U_l6rBzmy7bcy6xOJel4v0RzoR_wfAubGPeJimN__4', NULL, NULL, '人民日报', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_21b4383e542b8991bcd33d33eeda7d8d.jpeg?card_type=153&column_n=0&from=327834062', NULL, '', 1780985673050, 1780985754405, 7648102433310182671, '0', '2025年9月，习近平总书记在北京同金正恩总书记举行会谈时，特别提到2019年对朝鲜的国事访问，“庄严的中朝友谊塔、壮观的大型团体操表演、热情的朝鲜人民都给我留下了深刻的印象”。回顾这些瞬间，感受“中朝一家亲的浓厚氛围”！', '2025年9月，习近平总书记在北京同金正恩总书记举行会谈时，特别提到2019年对朝鲜的国事访问，“庄严的中朝友谊塔、壮观的大型团体操表演、热情的朝鲜人民都给我留下了深刻的印象”。回顾这些瞬间，感受“中朝一家亲的浓厚氛围”！', 1780712618, '475448', '13536', '7397', '35773', 'https://www.douyin.com/video/7648102433310182671', 'https://p3-pc-sign.douyinpic.com/obj/tos-cn-i-dy/9ed12fdf71ce4a1e8bb47c3547ff5347?lk3s=138a59ce&x-expires=2096344800&x-signature=Dg6VAO6%2BbucCyhGXDe%2FR3N66r6g%3D&from=327834062&s=PackSourceEnum_SEARCH&se=false&sc=cover&biz_tag=pcweb_cover&l=20260609141553AC68E4E13DA328FC8963', 'https://www.douyin.com/aweme/v1/play/?video_id=v0300fg10000d8ho977og65ouuadt6dg&line=0&file_id=a99a3c521c4146d3b724b0e4720df0cb&sign=b93a524a41752d3d6553cc930051e2ca&is_play_url=1&source=PackSourceEnum_SEARCH', '', '', '中朝关系');
